// Galois Field GF(2^8) arithmetic for AES (Rijndael).
// Field polynomial: x^8 + x^4 + x^3 + x + 1 (0x11b)

export function xtime(a) {
  a &= 0xff;
  return ((a << 1) ^ ((a & 0x80) ? 0x1b : 0x00)) & 0xff;
}

// Multiply two elements of GF(2^8).
export function gmul(a, b) {
  a &= 0xff;
  b &= 0xff;
  let p = 0;
  for (let i = 0; i < 8; i++) {
    if (b & 1) p ^= a;
    const hi = a & 0x80;
    a = (a << 1) & 0xff;
    if (hi) a ^= 0x1b;
    b >>= 1;
  }
  return p & 0xff;
}

// Multiplicative inverse in GF(2^8) via exponentiation (a^254).
export function ginv(a) {
  if (a === 0) return 0;
  let result = 1;
  let base = a & 0xff;
  let e = 254;
  while (e > 0) {
    if (e & 1) result = gmul(result, base);
    base = gmul(base, base);
    e >>= 1;
  }
  return result;
}

