// AES S-box and round constants, generated at load time from GF(2^8)
// arithmetic so no external data is required.
import { gmul, ginv } from './gf.mjs';

function rotl8(x, n) {
  return ((x << n) | (x >> (8 - n))) & 0xff;
}

function buildSBox() {
  const sbox = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    const inv = ginv(i);
    // Affine transformation: s = inv ^ rotl(inv,1) ^ rotl(inv,2) ^ rotl(inv,3) ^ rotl(inv,4) ^ 0x63
    sbox[i] =
      (inv ^
        rotl8(inv, 1) ^
        rotl8(inv, 2) ^
        rotl8(inv, 3) ^
        rotl8(inv, 4) ^
        0x63) &
      0xff;
  }
  return sbox;
}

export const SBOX = buildSBox();

// Round constants rcon[i] = 2^(i-1) in GF(2^8), for i = 1..10 (AES-128).
export const RCON = (() => {
  const rcon = new Uint8Array(11);
  let c = 1;
  for (let i = 1; i <= 10; i++) {
    rcon[i] = c;
    c = gmul(c, 2);
  }
  return rcon;
})();

