// AES-128 block cipher (encryption direction), reimplemented from the
// algorithm specification. State is a 16-byte array in column-major order,
// matching the AES standard (state[r][c] = bytes[r + 4*c]).
import { gmul } from './gf.mjs';
import { SBOX, RCON } from './tables.mjs';

const NR = 10; // rounds for a 128-bit key

// Expand a 16-byte key into 11 round keys (176 bytes total).
export function expandKey(key) {
  if (key.length !== 16) {
    throw new Error('AES-128 requires a 16-byte key');
  }
  const expanded = new Uint8Array(176);
  expanded.set(key);
  let bytesGenerated = 16;
  let rconIter = 1;
  const temp = new Uint8Array(4);

  while (bytesGenerated < 176) {
    for (let i = 0; i < 4; i++) temp[i] = expanded[bytesGenerated - 4 + i];
    if (bytesGenerated % 16 === 0) {
      // RotWord
      const t = temp[0];
      temp[0] = temp[1];
      temp[1] = temp[2];
      temp[2] = temp[3];
      temp[3] = t;
      // SubWord
      for (let i = 0; i < 4; i++) temp[i] = SBOX[temp[i]];
      temp[0] ^= RCON[rconIter++];
    }
    for (let i = 0; i < 4; i++) {
      expanded[bytesGenerated] = expanded[bytesGenerated - 16] ^ temp[i];
      bytesGenerated++;
    }
  }
  return expanded;
}

function addRoundKey(state, roundKeys, round) {
  const off = round * 16;
  for (let i = 0; i < 16; i++) state[i] ^= roundKeys[off + i];
}

function subBytes(state) {
  for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]];
}

function shiftRows(state) {
  // Row r is rotated left by r positions; index = r + 4*c.
  for (let r = 1; r < 4; r++) {
    const row = [state[r], state[r + 4], state[r + 8], state[r + 12]];
    for (let c = 0; c < 4; c++) {
      state[r + 4 * c] = row[(c + r) % 4];
    }
  }
}

function mixColumns(state) {
  for (let c = 0; c < 4; c++) {
    const i = 4 * c;
    const a0 = state[i];
    const a1 = state[i + 1];
    const a2 = state[i + 2];
    const a3 = state[i + 3];
    state[i] = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3;
    state[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3;
    state[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3);
    state[i + 3] = gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2);
  }
}

// Encrypt a single 16-byte block with the expanded key.
// Returns a new Uint8Array of 16 bytes.
export function encryptBlock(block, roundKeys) {
  if (block.length !== 16) {
    throw new Error('AES block must be exactly 16 bytes');
  }
  const state = Uint8Array.from(block);

  addRoundKey(state, roundKeys, 0);
  for (let round = 1; round < NR; round++) {
    subBytes(state);
    shiftRows(state);
    mixColumns(state);
    addRoundKey(state, roundKeys, round);
  }
  subBytes(state);
  shiftRows(state);
  addRoundKey(state, roundKeys, NR);

  return state;
}

