// AES ECB mode of operation, mirroring the pyaes.AESModeOfOperationECB
// interface used by the original Python script: constructed with a raw key,
// and encrypt() processes one block per call.
import { expandKey, encryptBlock } from './cipher.mjs';

export class AESModeOfOperationECB {
  constructor(key) {
    this._roundKeys = expandKey(key);
  }

  // Encrypt exactly one 16-byte block; returns a 16-byte Uint8Array.
  encrypt(block) {
    return encryptBlock(block, this._roundKeys);
  }
}

