// Reproduces Python's repr() for a bytes object, which is what print(bytes)
// emits. Quote selection and escape rules follow CPython's bytes_repr:
//  - single quotes by default; double quotes if the data contains a single
//    quote but no double quote;
//  - backslash and the active quote are backslash-escaped;
//  - \t, \n, \r use their short escapes;
//  - other non-printable bytes use \xNN (lowercase hex);
//  - printable ASCII (0x20..0x7e) is emitted verbatim.
export function bytesRepr(data) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of data) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (const b of data) {
    if (b === 0x5c) {
      out += '\\\\';
    } else if (b === quote.charCodeAt(0)) {
      out += '\\' + quote;
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

