// Minimal manual command-line parser matching the Python argparse setup:
//   parser.add_argument('--key', type=str, required=True)
//   parser.add_argument('--data', type=str, required=True)
// Both options take a single string value; both are required.
// Supports the same forms argparse accepts: `--opt value` and `--opt=value`.
export function parseArgs(argv) {
  const result = { key: undefined, data: undefined };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    let name = null;
    let value = null;

    if (arg === '--key' || arg === '--data') {
      name = arg.slice(2);
      if (i + 1 >= argv.length) {
        usageError(`argument ${arg}: expected one argument`);
      }
      value = argv[++i];
    } else if (arg.startsWith('--key=')) {
      name = 'key';
      value = arg.slice('--key='.length);
    } else if (arg.startsWith('--data=')) {
      name = 'data';
      value = arg.slice('--data='.length);
    } else {
      usageError(`unrecognized arguments: ${arg}`);
    }
    result[name] = value;
  }

  const missing = [];
  if (result.key === undefined) missing.push('--key');
  if (result.data === undefined) missing.push('--data');
  if (missing.length > 0) {
    usageError(
      `the following arguments are required: ${missing.join(', ')}`
    );
  }
  return result;
}

function usageError(message) {
  const prog = 'test16.mjs';
  console.error(`usage: ${prog} [-h] --key KEY --data DATA`);
  console.error(`${prog}: error: ${message}`);
  process.exit(2);
}

