// Entry point: Node.js port of /workspace/dataset/pyaes/test16.py
// Encrypts three 16-byte blocks of --data with AES-128 ECB under --key
// and prints each ciphertext in Python bytes-repr form.
import { AESModeOfOperationECB } from './aes/ecb.mjs';
import { bytesRepr } from './pybytes.mjs';
import { parseArgs } from './args.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2));

  // str.encode() in Python is UTF-8; TextEncoder matches.
  const encoder = new TextEncoder();
  const key = encoder.encode(args.key);
  const data = encoder.encode(args.data);

  const aes = new AESModeOfOperationECB(key);

  // Split into 16-byte blocks and encrypt each.
  const ciphertexts = [];
  for (let i = 0; i < data.length; i += 16) {
    const block = data.slice(i, i + 16);
    ciphertexts.push(aes.encrypt(block));
  }

  for (const cipher of ciphertexts) {
    console.log(bytesRepr(cipher));
  }
}

main();

