//  - unambiguous prefix abbreviations (e.g. --ke for --key)
//  - last occurrence wins for repeated options
//  - values starting with '-' are rejected as option arguments unless they
//    look like negative numbers (argparse's _negative_number_matcher)
//  - unknown options / extra positionals are collected and reported together
//  - -h / --help prints help and exits 0; errors print usage and exit 2

const LONG_OPTIONS = ['--help', '--key', '--data'];
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function prog() {
  const argv1 = process.argv[1] || 'test16.mjs';
  return argv1.split('/').pop();
}

function usageLine() {
  return `usage: ${prog()} [-h] --key KEY --data DATA`;
}

function printHelp() {
  console.log(usageLine());
  console.log('');
  console.log('options:');
  console.log('  -h, --help   show this help message and exit');
  console.log('  --key KEY');
  console.log('  --data DATA');
  process.exit(0);
}

function usageError(message) {
  console.error(usageLine());
  console.error(`${prog()}: error: ${message}`);
  process.exit(2);
}

// Resolve a `--xxx` token to a canonical long option name, honoring
// argparse's unambiguous-abbreviation rule. Returns null if unknown.
function resolveLong(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    usageError(`ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv) {
  const result = { key: undefined, data: undefined };
  const extras = [];
  let sawDoubleDash = false;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (sawDoubleDash) {
      extras.push(arg);
      continue;
    }
    if (arg === '--') {
      sawDoubleDash = true;
      continue;
    }
    if (arg === '-h') {
      printHelp();
    }

    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      const rawName = eq === -1 ? arg : arg.slice(0, eq);
      const name = resolveLong(rawName);
      if (name === null) {
        extras.push(arg);
        continue;
      }
      if (name === '--help') {
        printHelp();
      }
      let value;
      if (eq !== -1) {
        value = arg.slice(eq + 1);
      } else {
        const next = argv[i + 1];
        if (
          next === undefined ||
          (next.startsWith('-') && next.length > 1 && !NEGATIVE_NUMBER.test(next))
        ) {
          usageError(`argument ${name}: expected one argument`);
        }
        value = next;
        i++;
      }
      result[name.slice(2)] = value;
      continue;
    }

    // Short unknown option or positional.
    extras.push(arg);
  }

  const missing = [];
  if (result.key === undefined) missing.push('--key');
  if (result.data === undefined) missing.push('--data');
  if (missing.length > 0) {
    usageError(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    usageError(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return result;
}
